// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address arbitraryOwner) internal {
        bool ok1;
        try c.setOwner(arbitraryOwner) returns (bool __r) { ok1 = __r; } catch { return; }
        bool ok2;
        try c.setOwner(address(0)) returns (bool __r) { ok2 = __r; } catch { return; }
        assertTrue(ok1 && ok2);
    }

    function testFuzz_run(address arbitraryOwner) public {
        vm.assume(arbitraryOwner.code.length == 0 && uint160(arbitraryOwner) > 0xffff && arbitraryOwner != address(this) && arbitraryOwner != address(c) && arbitraryOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && arbitraryOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && arbitraryOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && arbitraryOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(arbitraryOwner);
    }

    receive() external payable {}
}
